import cf from 'cloudfront';

// Viewer-request function on /patterns/hello-fetch/*.
// GETs /hello on this pattern's origin and copies one JSON field into a request header.
// If the call fails, the request still goes through, with the error in x-hello-error.

const HELLO_ORIGIN_ID = 'hello-fetch';
const HELLO_PATH = '/hello';
const MESSAGE_HEADER = 'x-hello-message';
const STATUS_HEADER = 'x-hello-status';
const ERROR_HEADER = 'x-hello-error';

async function handler(event) {
  const request = event.request;
  // Never pass on viewer-supplied copies of the headers this function sets.
  delete request.headers[MESSAGE_HEADER];
  delete request.headers[STATUS_HEADER];
  delete request.headers[ERROR_HEADER];
  try {
    const helloResponse = await cf.fetch(HELLO_PATH, {
      originId: HELLO_ORIGIN_ID,
      includeBody: true, // default false; needed to read the body
    });
    const text = await helloResponse.text(); // assign first: no await inside call arguments
    const hello = JSON.parse(text);
    request.headers[MESSAGE_HEADER] = { value: String(hello.message) };
    request.headers[STATUS_HEADER] = { value: String(helloResponse.status) };
  } catch (error) {
    // TypeError, TimeoutError, InternalError, or a body that is not JSON.
    request.headers[ERROR_HEADER] = { value: error.name + ': ' + error.message };
  }
  return request;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/cognito-auth/*.
// Validates the viewer's Cognito access token with one call to Cognito GetUser
// (no SigV4: the token is the credential), then forwards the request with
// x-user-sub and x-user-name set. Anything else is denied before the origin:
//   no Bearer token          -> 401 missing_token, no call
//   token Cognito rejects    -> 401 invalid_token
//   Cognito cannot be asked  -> 503 auth_unavailable (fail closed)

const COGNITO_ORIGIN_ID = 'cognito-auth';
const GET_USER_TARGET = 'AWSCognitoIdentityProviderService.GetUser';
const BEARER_PREFIX = 'bearer ';
const IDENTITY_HEADER_PREFIX = 'x-user-';
const USER_SUB_HEADER = 'x-user-sub';
const USER_NAME_HEADER = 'x-user-name';
const ERROR_HEADER = 'x-cognito-auth-error';
const STATUS_TEXT = { 401: 'Unauthorized', 503: 'Service Unavailable' };

// Never trust identity headers coming from the viewer.
function stripIdentityHeaders(headers) {
  for (const name in headers) {
    if (name.indexOf(IDENTITY_HEADER_PREFIX) === 0) delete headers[name];
  }
}

// The token after "Bearer ", or null when the viewer sent no Bearer credential at all.
function readBearerToken(headers) {
  const authorization = headers.authorization ? headers.authorization.value : '';
  if (authorization.slice(0, BEARER_PREFIX.length).toLowerCase() !== BEARER_PREFIX) return null;
  return authorization.slice(BEARER_PREFIX.length).trim();
}

// The one network call. Resolves to the Cognito user, or null for a token Cognito rejects;
// throws when Cognito cannot be asked.
async function getCognitoUser(token) {
  const cognitoResponse = await cf.fetch('/', {
    originId: COGNITO_ORIGIN_ID,
    method: 'POST',
    headers: {
      'content-type': 'application/x-amz-json-1.1',
      'x-amz-target': GET_USER_TARGET,
    },
    body: JSON.stringify({ AccessToken: token }),
    includeBody: true, // default false; the user is in the body
  });
  // Cognito answers 400 NotAuthorizedException for a bad or expired token.
  if (!cognitoResponse.ok) return null;
  const text = await cognitoResponse.text(); // assign first: no await inside call arguments
  return JSON.parse(text);
}

// The value of a Cognito user attribute, '' when the user has none.
function userAttribute(user, name) {
  const attributes = user.UserAttributes || [];
  let value = '';
  for (let i = 0; i < attributes.length; i++) {
    if (attributes[i].Name === name) value = attributes[i].Value;
  }
  return value;
}

function deny(status, code, error) {
  const headers = {
    'content-type': { value: 'application/json' },
    'cache-control': { value: 'no-store' },
  };
  if (status === 401) headers['www-authenticate'] = { value: 'Bearer' };
  if (error) headers[ERROR_HEADER] = { value: error };
  return {
    statusCode: status,
    statusDescription: STATUS_TEXT[status],
    headers: headers,
    body: JSON.stringify({ error: code }),
  };
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  stripIdentityHeaders(headers);

  const token = readBearerToken(headers);
  if (token === null) return deny(401, 'missing_token');

  let user;
  try {
    user = await getCognitoUser(token);
  } catch (error) {
    // Fail closed: TypeError, TimeoutError, InternalError, or a body that is not JSON.
    return deny(503, 'auth_unavailable', error.name + ': ' + error.message);
  }

  const sub = user ? userAttribute(user, 'sub') : '';
  if (!sub) return deny(401, 'invalid_token');

  headers[USER_SUB_HEADER] = { value: sub };
  headers[USER_NAME_HEADER] = { value: String(user.Username) };
  return request;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/authorizer-headers/*.
// The API Gateway "Lambda authorizer + context" pattern at the edge: one call POSTs the
// viewer context to /authorize, the authorizer answers { allow, headers }, and the
// function copies those identity headers onto the request (allow) or answers 403 (deny).
// An authorizer that cannot be asked fails closed with 503.

const AUTHORIZER_ORIGIN_ID = 'authorizer-headers';
const AUTHORIZE_PATH = '/authorize';
// The only headers the authorizer may set. Viewers can never supply them.
const IDENTITY_HEADERS = ['x-tenant', 'x-role'];
const ERROR_HEADER = 'x-authorizer-headers-error';
const STATUS_TEXT = { 403: 'Forbidden', 503: 'Service Unavailable' };

function headerValue(headers, name) {
  return headers[name] ? headers[name].value : '';
}

// Never trust identity headers coming from the viewer.
function stripIdentityHeaders(headers) {
  for (let i = 0; i < IDENTITY_HEADERS.length; i++) delete headers[IDENTITY_HEADERS[i]];
}

// What the authorizer decides on: who is asking, for what.
function viewerContext(event) {
  const request = event.request;
  return {
    ip: event.viewer.ip,
    uri: request.uri,
    method: request.method,
    headers: {
      authorization: headerValue(request.headers, 'authorization'),
      'user-agent': headerValue(request.headers, 'user-agent'),
    },
  };
}

// The one network call. Resolves to { ok, status, decision }; throws when the authorizer
// cannot be asked or its answer is not JSON.
async function askAuthorizer(context) {
  const body = JSON.stringify(context);
  const authorizerResponse = await cf.fetch(AUTHORIZE_PATH, {
    originId: AUTHORIZER_ORIGIN_ID,
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: body,
    includeBody: true, // default false; the decision is in the body
  });
  if (!authorizerResponse.ok) return { ok: false, status: authorizerResponse.status };
  const text = await authorizerResponse.text(); // assign first: no await inside call arguments
  return { ok: true, status: authorizerResponse.status, decision: JSON.parse(text) };
}

// Copy only the allowlisted identity headers, lowercased.
function grantIdentityHeaders(headers, granted) {
  for (const name in granted) {
    const lowerName = name.toLowerCase();
    if (IDENTITY_HEADERS.indexOf(lowerName) !== -1) headers[lowerName] = { value: String(granted[name]) };
  }
}

function deny(status, code, error) {
  const headers = {
    'content-type': { value: 'application/json' },
    'cache-control': { value: 'no-store' },
  };
  if (error) headers[ERROR_HEADER] = { value: error };
  return {
    statusCode: status,
    statusDescription: STATUS_TEXT[status],
    headers: headers,
    body: JSON.stringify({ error: code }),
  };
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  stripIdentityHeaders(headers);

  let answer;
  try {
    answer = await askAuthorizer(viewerContext(event));
  } catch (error) {
    // Fail closed: TypeError, TimeoutError, InternalError, or a body that is not JSON.
    return deny(503, 'authorizer_unavailable', error.name + ': ' + error.message);
  }
  if (!answer.ok) return deny(503, 'authorizer_unavailable', 'authorizer returned ' + answer.status);

  const decision = answer.decision;
  if (!decision || decision.allow !== true) return deny(403, 'forbidden');

  grantIdentityHeaders(headers, decision.headers || {});
  return request;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/bot-check-fail-open/*.
// Two lookups run in parallel:
//   1. One call: POST /check on the mock vendor. The only latency limit is the
//      runtime's fixed 1 s timeout (no option, and Date.now() does not advance
//      across the await, so a tighter budget cannot be timed here).
//   2. kvs.get('bot-policy'): block | tag | off. Missing KVS or key -> tag.
// Vendor slow or broken -> forward with x-bot-check: unavailable (fail open).
// Verdict bot + block   -> 403 block page.
// Verdict bot + tag     -> forward with x-bot-verdict: bot, the origin decides.
// Policy off            -> forward, verdict ignored.

const VENDOR_ORIGIN_ID = 'bot-check-fail-open';
const CHECK_PATH = '/check';
const BOT_POLICY_KEY = 'bot-policy';
const POLICIES = ['block', 'tag', 'off'];
const DEFAULT_POLICY = 'tag';
const BOT_HEADER_PREFIX = 'x-bot-';
const POLICY_HEADER = 'x-bot-policy';
const POLICY_SOURCE_HEADER = 'x-bot-policy-source';
const CHECK_HEADER = 'x-bot-check';
const VERDICT_HEADER = 'x-bot-verdict';
const SCORE_HEADER = 'x-bot-score';
const ERROR_HEADER = 'x-bot-check-fail-open-error';

function headerValue(request, name) {
  return request.headers[name] ? request.headers[name].value : '';
}

function describeError(error) {
  return error.name + ': ' + error.message;
}

// Never trust verdict headers coming from the viewer.
function stripBotHeaders(headers) {
  for (const name in headers) {
    if (name.indexOf(BOT_HEADER_PREFIX) === 0) delete headers[name];
  }
}

// The one network call. Resolves to { verdict, score } or throws.
async function askVendor(request, viewer) {
  const body = JSON.stringify({
    path: request.uri,
    ip: viewer.ip,
    userAgent: headerValue(request, 'user-agent'),
    acceptLanguage: headerValue(request, 'accept-language'),
    // Demo knobs, passed through so curl can steer the mock.
    forceVerdict: headerValue(request, 'x-force-verdict'),
    delayMs: headerValue(request, 'x-mock-delay-ms'),
  });
  const vendorResponse = await cf.fetch(CHECK_PATH, {
    originId: VENDOR_ORIGIN_ID,
    method: 'POST',
    headers: { // plain strings, not { value } objects
      'content-type': 'application/json',
    },
    body: body,
    includeBody: true, // default false; the verdict is in the body
  });
  if (!vendorResponse.ok) throw new Error('vendor returned ' + vendorResponse.status);

  const text = await vendorResponse.text(); // assign first: no await inside call arguments
  const answer = JSON.parse(text);
  if (answer.verdict !== 'bot' && answer.verdict !== 'human') throw new Error('vendor verdict unreadable');
  return { verdict: answer.verdict, score: Number(answer.score) || 0 };
}

// Rejects when no KVS is associated, the key is missing or the value is unknown.
async function readPolicy() {
  const value = await cf.kvs().get(BOT_POLICY_KEY);
  const policy = String(value).trim().toLowerCase();
  if (POLICIES.indexOf(policy) === -1) throw new Error(BOT_POLICY_KEY + ' "' + policy + '" is not block|tag|off');
  return policy;
}

function blockPage(check) {
  return {
    statusCode: 403,
    statusDescription: 'Forbidden',
    headers: {
      'content-type': { value: 'text/html; charset=utf-8' },
      'cache-control': { value: 'no-store' },
      [VERDICT_HEADER]: { value: 'bot' },
      [SCORE_HEADER]: { value: String(check.score) },
    },
    body: '<!doctype html><title>Blocked</title><h1>403 Blocked</h1>' +
      '<p>The bot check said bot (score ' + check.score + ') and the KVS key ' + BOT_POLICY_KEY + ' is block.</p>',
  };
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  stripBotHeaders(headers);

  // allSettled, not all: a missing KVS key must not throw away the vendor verdict.
  const results = await Promise.allSettled([askVendor(request, event.viewer), readPolicy()]);
  const vendorResult = results[0];
  const policyResult = results[1];

  const fromKvs = policyResult.status === 'fulfilled';
  const policy = fromKvs ? policyResult.value : DEFAULT_POLICY;
  headers[POLICY_HEADER] = { value: policy };
  headers[POLICY_SOURCE_HEADER] = { value: fromKvs ? 'kvs' : 'default: ' + describeError(policyResult.reason) };

  if (vendorResult.status === 'rejected') {
    // Fail open: TypeError, TimeoutError, InternalError, a bad status or an unreadable verdict.
    headers[CHECK_HEADER] = { value: 'unavailable' };
    headers[ERROR_HEADER] = { value: describeError(vendorResult.reason) };
    return request;
  }

  const check = vendorResult.value;
  headers[CHECK_HEADER] = { value: 'ok' };
  if (policy === 'off') return request;

  headers[VERDICT_HEADER] = { value: check.verdict };
  headers[SCORE_HEADER] = { value: String(check.score) };
  if (check.verdict === 'bot' && policy === 'block') return blockPage(check);
  return request;
}

import cf from 'cloudfront';
import crypto from 'crypto';

// Viewer-request function on /patterns/ab-global-table/*.
// Sticky A/B: the uid cookie names the user, the KVS holds the warm working set,
// DynamoDB (global table) behind the origin is the source of truth.
//   KVS hit  -> x-ab-variant from KVS, no network call
//   KVS miss -> one call: POST /assign/<uid> on this pattern's origin
//   failure  -> x-ab-variant: control and x-ab-error, request still forwarded
// This side never sets a cookie: response-function.js turns x-ab-set-uid and
// x-ab-set-variant into Set-Cookie.

const ASSIGNER_ORIGIN_ID = 'ab-global-table';
const ASSIGN_PATH = '/assign/';
const UID_COOKIE = 'uid';
const UID_PATTERN = /^[a-f0-9]{16}$/;
const UID_LENGTH = 16;
const FALLBACK_VARIANT = 'control';
// Read by response-function.js: only this function may set them.
const SET_UID_HEADER = 'x-ab-set-uid';
const SET_VARIANT_HEADER = 'x-ab-set-variant';
// Forwarded to the origin.
const UID_HEADER = 'x-ab-uid';
const NEW_UID_HEADER = 'x-ab-uid-new';
const KVS_HEADER = 'x-ab-kvs';
const VARIANT_HEADER = 'x-ab-variant';
const SOURCE_HEADER = 'x-ab-source';
const ERROR_HEADER = 'x-ab-error';

function isVariant(value) {
  return value === 'A' || value === 'B';
}

// Unique enough per browser. Not Math.random(): a function cannot make a network call
// after generating random values, so it hashes the request id instead.
function newUid(event) {
  const seed = event.context.requestId + event.viewer.ip + Date.now();
  return crypto.createHash('sha256').update(seed).digest('hex').slice(0, UID_LENGTH);
}

// The viewer's uid cookie, or a new uid that the response side will set as a cookie.
function readOrIssueUid(event) {
  const request = event.request;
  const cookie = request.cookies[UID_COOKIE];
  const uid = cookie ? cookie.value : '';
  if (UID_PATTERN.test(uid)) return uid;

  const issued = newUid(event);
  request.cookies[UID_COOKIE] = { value: issued };
  request.headers[NEW_UID_HEADER] = { value: '1' };
  request.headers[SET_UID_HEADER] = { value: issued };
  return issued;
}

// The one network call, on a KVS miss. Resolves to A or B, or throws.
async function assignVariant(uid) {
  const assignResponse = await cf.fetch(ASSIGN_PATH + uid, {
    originId: ASSIGNER_ORIGIN_ID,
    method: 'POST',
    includeBody: true, // default false; the variant is in the body
  });
  const text = await assignResponse.text(); // assign first: no await inside call arguments
  const assignment = JSON.parse(text);
  if (!isVariant(assignment.variant)) throw new Error('bad assign response, status ' + assignResponse.status);
  return assignment.variant;
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  // Only this function may talk to the response side: drop viewer-supplied copies.
  delete headers[SET_UID_HEADER];
  delete headers[SET_VARIANT_HEADER];

  const uid = readOrIssueUid(event);
  headers[UID_HEADER] = { value: uid };

  // 1. KVS. A missing key, or no KVS associated, throws: that is a miss.
  let variant = '';
  let source = 'kvs';
  try {
    variant = await cf.kvs().get(uid);
    headers[KVS_HEADER] = { value: 'hit' };
  } catch (error) {
    headers[KVS_HEADER] = { value: 'miss: ' + error.message };
  }

  // 2. Miss: one call to the assigner.
  if (!isVariant(variant)) {
    try {
      variant = await assignVariant(uid);
      source = 'origin';
    } catch (error) {
      // TypeError, TimeoutError, InternalError, or a bad body: forward as control.
      variant = FALLBACK_VARIANT;
      source = 'fallback';
      headers[ERROR_HEADER] = { value: error.name + ': ' + error.message };
    }
  }

  headers[VARIANT_HEADER] = { value: variant };
  headers[SOURCE_HEADER] = { value: source };
  if (variant !== FALLBACK_VARIANT) headers[SET_VARIANT_HEADER] = { value: variant };
  return request;
}

// Viewer-response function on /patterns/ab-global-table/*.
// The request function decided (KVS first, ONE cf.fetch on a miss) and left the
// decision on the request as x-ab-set-uid / x-ab-set-variant. This side only
// turns those into cookies. No cf.fetch, no KVS: this hook runs on cache hits
// too, so it must stay cheap.

const SET_UID_HEADER = 'x-ab-set-uid';
const SET_VARIANT_HEADER = 'x-ab-set-variant';
const HOOKS_HEADER = 'x-ab-hooks';
const UID_COOKIE = 'uid';
const VARIANT_COOKIE = 'ab';
const UID_PATTERN = /^[a-f0-9]{16}$/;
const COOKIE_ATTRIBUTES = 'Path=/patterns/ab-global-table/; Max-Age=86400; Secure; HttpOnly; SameSite=Lax';

function headerValue(headers, name) {
  return headers[name] ? headers[name].value : '';
}

function handler(event) {
  const requestHeaders = event.request.headers;
  const response = event.response;
  const uid = headerValue(requestHeaders, SET_UID_HEADER);
  const variant = headerValue(requestHeaders, SET_VARIANT_HEADER);

  if (UID_PATTERN.test(uid)) response.cookies[UID_COOKIE] = { value: uid, attributes: COOKIE_ATTRIBUTES };
  if (variant === 'A' || variant === 'B') {
    response.cookies[VARIANT_COOKIE] = { value: variant, attributes: COOKIE_ATTRIBUTES };
  }
  response.headers[HOOKS_HEADER] = { value: 'request+response' };
  return response;
}

import cf from 'cloudfront';
import crypto from 'crypto';

// Viewer-request function on /patterns/edge-signal-sqs/*.
// Fires a small JSON signal at this pattern's origin (API Gateway -> SQS FIFO, no Lambda)
// with cf.beacon, then forwards the request whatever happened.
//   x-signal: beacon -> handed off; nothing to await, no response to read
//   x-signal: failed -> cf.beacon threw (x-signal-error)
// cf.beacon still counts as the one network call per invocation.

const QUEUE_ORIGIN_ID = 'edge-signal-sqs';
const SIGNAL_PATH = '/patterns/signal';
const MAX_DEDUP_ID_LENGTH = 128; // SQS FIFO limit
const MAX_USER_AGENT_LENGTH = 200;
const VIEWER_HASH_LENGTH = 16;
const SIGNAL_ID_HEADER = 'x-signal-id';
const SIGNAL_HEADER = 'x-signal';
const ERROR_HEADER = 'x-signal-error';

// Never ship the raw viewer IP: a truncated hash is enough to tell viewers apart.
function hashViewerIp(ip) {
  return crypto.createHash('sha256').update(ip).digest('hex').slice(0, VIEWER_HASH_LENGTH);
}

function requestedSignal(event, signalId) {
  const userAgent = event.request.headers['user-agent'] ? event.request.headers['user-agent'].value : '';
  return {
    kind: 'requested',
    uri: signalId,
    ip: hashViewerIp(event.viewer.ip),
    ua: userAgent.slice(0, MAX_USER_AGENT_LENGTH),
    ts: Date.now(),
  };
}

async function handler(event) {
  const request = event.request;

  // FIFO dedup id (the API Gateway mapping uses it).
  const signalId = request.uri.slice(0, MAX_DEDUP_ID_LENGTH);
  // Carried forward so response-function.js can correlate its "served" event.
  request.headers[SIGNAL_ID_HEADER] = { value: signalId };

  try {
    cf.beacon(SIGNAL_PATH, {
      originId: QUEUE_ORIGIN_ID,
      method: 'POST',
      headers: { 'content-type': 'application/json' }, // plain strings, not { value } objects
      body: JSON.stringify(requestedSignal(event, signalId)),
      logDeliveryErrors: true, // a delivery failure after the function returned goes to CloudWatch Logs
    });
    request.headers[SIGNAL_HEADER] = { value: 'beacon' };
  } catch (error) {
    // Only invalid calls throw here (TypeError): a bad option, or a second call in one invocation.
    request.headers[SIGNAL_HEADER] = { value: 'failed' };
    request.headers[ERROR_HEADER] = { value: error.name + ': ' + error.message };
  }
  return request;
}

import cf from 'cloudfront';

// Viewer-response function on /patterns/edge-signal-sqs/*: the way out.
// The viewer-response hook runs on every response, cache hits included, so a call here
// must be rare by construction: it fires only when the origin answered 5xx, or when the
// viewer asked for a sample (x-signal-sample: 1). Everything else gets
// x-signal-served: skipped and no call.
// CloudFront does not run viewer-response functions when the origin returns 400 or
// higher, so on the live demo the sample switch is what makes the call visible.

const QUEUE_ORIGIN_ID = 'edge-signal-sqs';
const SIGNAL_PATH = '/patterns/signal';
const MAX_DEDUP_ID_LENGTH = 128; // SQS FIFO limit
const FIRST_SERVER_ERROR = 500;
const SAMPLE_HEADER = 'x-signal-sample';
const SIGNAL_ID_HEADER = 'x-signal-id';
const SERVED_HEADER = 'x-signal-served';
const ERROR_HEADER = 'x-signal-served-error';

function headerValue(headers, name) {
  return headers[name] ? headers[name].value : '';
}

// Rare by construction: an origin 5xx, or an explicit sample request.
function shouldSignal(request, status) {
  return status >= FIRST_SERVER_ERROR || headerValue(request.headers, SAMPLE_HEADER) === '1';
}

function servedSignal(request, status) {
  const uri = request.uri.slice(0, MAX_DEDUP_ID_LENGTH);
  return {
    kind: 'served',
    uri: uri,
    status: status,
    // Correlates with the "requested" event that function.js sent on the way in.
    signalId: headerValue(request.headers, SIGNAL_ID_HEADER) || uri,
    // Its own FIFO dedup id, so it never collapses into the "requested" event.
    dedupId: ('served:' + uri + ':' + status).slice(0, MAX_DEDUP_ID_LENGTH),
    ts: Date.now(),
  };
}

async function handler(event) {
  const request = event.request;
  const response = event.response;
  const status = response.statusCode;

  if (!shouldSignal(request, status)) {
    response.headers[SERVED_HEADER] = { value: 'skipped' };
    return response;
  }

  try {
    cf.beacon(SIGNAL_PATH, {
      originId: QUEUE_ORIGIN_ID,
      method: 'POST',
      headers: { 'content-type': 'application/json' }, // plain strings, not { value } objects
      body: JSON.stringify(servedSignal(request, status)),
      logDeliveryErrors: true, // a delivery failure after the function returned goes to CloudWatch Logs
    });
    response.headers[SERVED_HEADER] = { value: 'beacon' };
  } catch (error) {
    response.headers[SERVED_HEADER] = { value: 'failed' };
    response.headers[ERROR_HEADER] = { value: error.name + ': ' + error.message };
  }
  return response;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/vpc-private-routing/*.
// 1. KVS kill switch: routing-kill-switch = off forwards unchanged, with no call.
// 2. One call: GET /route?tenant=<x> on the private ALB (a VPC origin).
// 3. Rewrite the URI to /patterns/vpc-private-routing/<backend>/... and set x-backend.
// Any failure forwards unchanged, with x-vpc-private-routing-error.

const ROUTER_ORIGIN_ID = 'vpc-private-routing';
const ROUTE_PATH = '/route?tenant=';
const PATH_PREFIX = '/patterns/vpc-private-routing';
const KILL_SWITCH_KEY = 'routing-kill-switch';
const BACKENDS = ['blue', 'green'];
const DEFAULT_TENANT = 'guest';
const TENANT_HEADER = 'x-tenant';
const BACKEND_HEADER = 'x-backend';
const KVS_ERROR_HEADER = 'x-vpc-private-routing-kvs-error';
const ERROR_HEADER = 'x-vpc-private-routing-error';

function describeError(error) {
  return error.name + ': ' + error.message;
}

// ?tenant=<x> wins, then an x-tenant header, else "guest".
function readTenant(request) {
  const fromQuery = request.querystring.tenant;
  if (fromQuery && fromQuery.value) return fromQuery.value;
  const fromHeader = request.headers[TENANT_HEADER];
  if (fromHeader && fromHeader.value) return fromHeader.value;
  return DEFAULT_TENANT;
}

// A missing key means routing is on. Any other KVS error also leaves routing on, and is reported.
async function routingSwitchedOff(headers) {
  try {
    const killSwitch = await cf.kvs().get(KILL_SWITCH_KEY);
    return killSwitch === 'off';
  } catch (error) {
    if (error.message.indexOf('KeyNotFound') === -1) headers[KVS_ERROR_HEADER] = { value: describeError(error) };
    return false;
  }
}

// The one network call. Resolves to blue or green, or throws.
async function lookupBackend(tenant) {
  const routeResponse = await cf.fetch(ROUTE_PATH + encodeURIComponent(tenant), {
    originId: ROUTER_ORIGIN_ID,
    includeBody: true, // default false; the backend is in the body
  });
  if (!routeResponse.ok) throw new Error('route service returned ' + routeResponse.status);
  const text = await routeResponse.text(); // assign first: no await inside call arguments
  const route = JSON.parse(text);
  if (BACKENDS.indexOf(route.backend) === -1) throw new Error('unknown backend ' + route.backend);
  return route.backend;
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  const tenant = readTenant(request);
  headers[TENANT_HEADER] = { value: tenant };

  if (await routingSwitchedOff(headers)) {
    headers[BACKEND_HEADER] = { value: 'off' };
    return request;
  }

  try {
    const backend = await lookupBackend(tenant);
    request.uri = PATH_PREFIX + '/' + backend + request.uri.slice(PATH_PREFIX.length);
    headers[BACKEND_HEADER] = { value: backend };
  } catch (error) {
    // TypeError, TimeoutError, InternalError, or a bad answer: forward unchanged.
    headers[ERROR_HEADER] = { value: describeError(error) };
  }
  return request;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/kvs-config-plus-fetch/<key>.
// Read-through config per key (a tenant, an API key, a model route):
//   fresh KVS entry -> use it, no network call
//   miss or expired -> one call: GET /config/<key> on this pattern's origin
//   call fails      -> the expired KVS entry if there is one, else DEFAULT_CONFIG; the request is never blocked
// The origin counts reads per key, and hot keys are written to KVS off the request path,
// so their next reads are KVS hits. The result is forwarded in the x-config-* headers.

const CONFIG_ORIGIN_ID = 'kvs-config-plus-fetch';
const PATH_PREFIX = '/patterns/kvs-config-plus-fetch/';
const CONFIG_PATH = '/config/';
const KVS_KEY_PREFIX = 'cfg-'; // the promoter writes { exp, config } under cfg-<key>
const DEFAULT_KEY = 'default';
const KEY_PATTERN = /^[a-z0-9-]{1,32}$/;
const DEFAULT_CONFIG = { plan: 'free', model: 'small', rateLimit: 10 };
const CONFIG_HEADER = 'x-config';
const KEY_HEADER = 'x-config-key';
const SOURCE_HEADER = 'x-config-source';
const HITS_HEADER = 'x-config-hits';
const ERROR_HEADER = 'x-config-error';
const OWN_HEADERS = [CONFIG_HEADER, KEY_HEADER, SOURCE_HEADER, HITS_HEADER, ERROR_HEADER];

function badKey() {
  return { statusCode: 400, statusDescription: 'Bad Request', body: 'key must be 1-32 characters of a-z, 0-9 and -' };
}

// A missing key, or no KVS associated, throws: that is a miss.
async function readCachedEntry(key) {
  try {
    return await cf.kvs().get(KVS_KEY_PREFIX + key, { format: 'json' });
  } catch (error) {
    return null;
  }
}

// exp is in seconds, as the promoter writes it.
function isFresh(entry) {
  return entry.exp * 1000 > Date.now();
}

// The one network call, which also counts the read. Resolves to { config, hits, threshold }, or throws.
async function fetchConfig(key) {
  const configResponse = await cf.fetch(CONFIG_PATH + key, {
    originId: CONFIG_ORIGIN_ID,
    includeBody: true, // default false; the config is in the body
  });
  if (!configResponse.ok) throw new Error('origin returned ' + configResponse.status);
  const text = await configResponse.text(); // assign first: no await inside call arguments
  const answer = JSON.parse(text);
  if (!answer.config) throw new Error('no config in the origin response');
  return answer;
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  // Only this function may set these for the origin: drop viewer-supplied copies.
  OWN_HEADERS.forEach((name) => delete headers[name]);

  const key = request.uri.slice(PATH_PREFIX.length).split('/')[0] || DEFAULT_KEY;
  if (!KEY_PATTERN.test(key)) return badKey();

  const cached = await readCachedEntry(key);
  let config = DEFAULT_CONFIG;
  let source = 'default';
  if (cached && isFresh(cached)) {
    config = cached.config;
    source = 'kvs';
  } else {
    try {
      const fetched = await fetchConfig(key);
      config = fetched.config;
      source = 'origin';
      if (typeof fetched.hits === 'number') headers[HITS_HEADER] = { value: fetched.hits + '/' + fetched.threshold };
    } catch (error) {
      // TypeError, TimeoutError, InternalError, a bad status or body: fail open, stale beats default.
      headers[ERROR_HEADER] = { value: error.name + ': ' + error.message };
      if (cached) {
        config = cached.config;
        source = 'kvs-stale';
      }
    }
  }

  headers[KEY_HEADER] = { value: key };
  headers[SOURCE_HEADER] = { value: source };
  headers[CONFIG_HEADER] = { value: JSON.stringify(config) };
  return request;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/origin-health-fallback/*.
// Failover for POST, which origin groups cannot do: they only fail over GET, HEAD and
// OPTIONS, so a POST to a primary that is down simply fails. This function decides
// before the request leaves the edge, with one call: GET /health on the primary.
// "Slow" means the runtime's fixed 1 s TimeoutError (no option, and Date.now() does
// not advance across the await, so a tighter budget cannot be timed here).
//   2xx                                           -> x-route: primary
//   non-2xx, TimeoutError, InternalError, or a
//   TypeError "... due to <result type>" (the edge
//   could not reach the primary: DNS, TLS, connect) -> x-route: fallback
//       POST, PUT, PATCH, DELETE -> the secondary Lambda
//       GET, HEAD                -> the S3 mirror
//   any other TypeError (the call itself is invalid) -> x-route: primary (fail open)
// GET and HEAD on the primary route also get an origin group (primary, then the
// mirror on 5xx). The probe costs a call per request, so it runs only when the KVS
// key health-probe is on.

const PRIMARY_ORIGIN_ID = 'origin-health-fallback';
const MIRROR_ORIGIN_ID = 'origin-health-fallback-static';
const SECONDARY_ORIGIN_ID = 'origin-health-fallback-secondary';
const HEALTH_PATH = '/health';
const PROBE_SWITCH_KEY = 'health-probe';
const FAILOVER_STATUS_CODES = [500, 502, 503, 504];
const ROUTE_HEADER = 'x-route';
const ROUTE_ERROR_HEADER = 'x-route-error';
const PROBE_HEADER = 'x-health-probe';
const PROBE_ERROR_HEADER = 'x-health-probe-error';

function describeError(error) {
  return error.name + ': ' + error.message;
}

// The runtime also uses TypeError when the edge could not reach the origin, naming the
// x-edge-detailed-result-type: "The request could not be completed due to OriginDnsError".
// That says the primary is down, so it fails over; any other TypeError is a bad call.
function originUnreachable(error) {
  return error.name === 'TypeError' && error.message.indexOf('could not be completed due to') !== -1;
}

// Never trust routing headers coming from the viewer.
function stripRoutingHeaders(headers) {
  delete headers[ROUTE_HEADER];
  delete headers[ROUTE_ERROR_HEADER];
  delete headers[PROBE_HEADER];
  delete headers[PROBE_ERROR_HEADER];
}

// ?probe=on|off wins (for the demo), then the KVS key health-probe. Default off.
async function probeEnabled(request) {
  const fromQuery = request.querystring.probe;
  if (fromQuery && (fromQuery.value === 'on' || fromQuery.value === 'off')) return fromQuery.value === 'on';
  try {
    const probeSwitch = await cf.kvs().get(PROBE_SWITCH_KEY);
    return probeSwitch === 'on';
  } catch (error) {
    return false;
  }
}

// /health, plus ?simulate=<x> for the demo: it makes the primary slow or down.
function healthPath(request) {
  const simulate = request.querystring.simulate;
  return simulate ? HEALTH_PATH + '?simulate=' + simulate.value : HEALTH_PATH;
}

// The one network call. Resolves to { route, probe }; never throws.
async function probePrimary(request, headers) {
  try {
    // No body read (includeBody defaults to false): the status is the verdict.
    const healthResponse = await cf.fetch(healthPath(request), { originId: PRIMARY_ORIGIN_ID });
    if (!healthResponse.ok) return { route: 'fallback', probe: 'unhealthy:' + healthResponse.status };
    return { route: 'primary', probe: 'ok' };
  } catch (error) {
    headers[PROBE_ERROR_HEADER] = { value: describeError(error) };
    // A bad call says nothing about the origin: fail open.
    if (error.name === 'TypeError' && !originUnreachable(error)) return { route: 'primary', probe: 'unavailable' };
    return { route: 'fallback', probe: error.name === 'TimeoutError' ? 'unhealthy:timeout' : 'unhealthy:error' };
  }
}

// Fallback: the mirror can replay a GET or HEAD, only the secondary can take a write.
// Primary: a GET or HEAD still fails over to the mirror on 5xx.
function selectOrigins(route, replayable) {
  if (route === 'fallback') {
    cf.selectRequestOriginById(replayable ? MIRROR_ORIGIN_ID : SECONDARY_ORIGIN_ID);
  } else if (replayable) {
    cf.createRequestOriginGroup({
      originIds: [{ originId: PRIMARY_ORIGIN_ID }, { originId: MIRROR_ORIGIN_ID }],
      failoverCriteria: { statusCodes: FAILOVER_STATUS_CODES },
    });
  }
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  stripRoutingHeaders(headers);
  if (request.uri.slice(-1) === '/') request.uri += 'index.html';
  const replayable = request.method === 'GET' || request.method === 'HEAD';

  let health = { route: 'primary', probe: 'off' };
  if (await probeEnabled(request)) health = await probePrimary(request, headers);

  try {
    selectOrigins(health.route, replayable);
  } catch (error) {
    // The request still goes to the primary.
    headers[ROUTE_ERROR_HEADER] = { value: describeError(error) };
  }
  headers[ROUTE_HEADER] = { value: health.route };
  headers[PROBE_HEADER] = { value: health.probe };
  return request;
}

// Viewer-response function on /patterns/origin-health-fallback/*. No network call.
// CloudFront does not run viewer-response functions when the origin answered 400 or
// higher, so this only ever sees successes and only annotates them:
//   x-served-by: primary    the primary Lambda set x-origin: lambda
//   x-served-by: secondary  the standby Lambda set x-origin: lambda-secondary
//   x-served-by: fallback   no marker: the S3 mirror answered
//   x-fallback: true        on anything but primary
// It also copies the request function's verdict headers onto the response.
// Compare x-route with x-served-by to tell "probe decided" from "group failed over".

const ORIGIN_MARKER_HEADER = 'x-origin';
const SERVED_BY_HEADER = 'x-served-by';
const FALLBACK_HEADER = 'x-fallback';
const PRIMARY_MARKER = 'lambda';
const SECONDARY_MARKER = 'lambda-secondary';
const VERDICT_HEADERS = ['x-route', 'x-health-probe', 'x-health-probe-error', 'x-route-error'];

function servedBy(marker) {
  if (marker === PRIMARY_MARKER) return 'primary';
  if (marker === SECONDARY_MARKER) return 'secondary';
  return 'fallback';
}

function copyVerdictHeaders(requestHeaders, responseHeaders) {
  for (let i = 0; i < VERDICT_HEADERS.length; i++) {
    const header = requestHeaders[VERDICT_HEADERS[i]];
    if (header) responseHeaders[VERDICT_HEADERS[i]] = { value: header.value };
  }
}

function handler(event) {
  const headers = event.response.headers;

  // The marker is internal: read it, then drop it.
  const marker = headers[ORIGIN_MARKER_HEADER] ? headers[ORIGIN_MARKER_HEADER].value : '';
  delete headers[ORIGIN_MARKER_HEADER];
  const origin = servedBy(marker);
  headers[SERVED_BY_HEADER] = { value: origin };
  if (origin !== 'primary') headers[FALLBACK_HEADER] = { value: 'true' };

  copyVerdictHeaders(event.request.headers, headers);
  return event.response;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/agent-authz/*.
// An AI agent sends a scoped token on every request. The token proves who the agent is, not
// whether it may touch THIS resource right now, so the function asks the authorization service
// with one POST /v1/check { action, resource, token } and forwards the request only on
// { allowed: true }. No token: 401, no call. Not allowed: 403. A service that cannot be asked
// fails closed with 503. Viewer request runs before the cache, so allowed reads can be cache hits.

const AUTHZ_ORIGIN_ID = 'agent-authz';
const CHECK_PATH = '/v1/check';
const ERROR_HEADER = 'x-agent-authz-error';
const STATUS_TEXT = { 401: 'Unauthorized', 403: 'Forbidden', 503: 'Service Unavailable' };

// What the agent wants to do: read or write this URI, with this token.
function accessCheck(request, token) {
  return {
    action: request.method === 'GET' || request.method === 'HEAD' ? 'read' : 'write',
    resource: request.uri,
    // In the body, not the authorization header: OAC signs the call and owns that header.
    token: token,
  };
}

// The one network call. Resolves to { ok, status, decision }; throws when the service
// cannot be asked or its answer is not JSON.
async function askAuthz(check) {
  const body = JSON.stringify(check);
  const authzResponse = await cf.fetch(CHECK_PATH, {
    originId: AUTHZ_ORIGIN_ID,
    method: 'POST',
    headers: {
      'content-type': 'application/json',
    },
    body: body,
    includeBody: true, // default false; the decision is in the body
  });
  if (!authzResponse.ok) return { ok: false, status: authzResponse.status };
  const text = await authzResponse.text(); // assign first: no await inside call arguments
  return { ok: true, status: authzResponse.status, decision: JSON.parse(text) };
}

function deny(status, code, error) {
  const headers = {
    'content-type': { value: 'application/json' },
    'cache-control': { value: 'no-store' },
  };
  if (status === 401) headers['www-authenticate'] = { value: 'Bearer' };
  if (error) headers[ERROR_HEADER] = { value: error };
  return { statusCode: status, statusDescription: STATUS_TEXT[status], headers: headers, body: JSON.stringify({ error: code }) };
}

async function handler(event) {
  const request = event.request;
  const authorization = request.headers.authorization;
  // No header, or an empty one: refuse here, without spending the call.
  if (!authorization || !authorization.value.trim()) return deny(401, 'unauthorized');

  let answer;
  try {
    answer = await askAuthz(accessCheck(request, authorization.value));
  } catch (error) {
    // Fail closed: TypeError, TimeoutError, InternalError, or a body that is not JSON.
    return deny(503, 'authz_unavailable', error.name + ': ' + error.message);
  }
  if (!answer.ok) return deny(503, 'authz_unavailable', 'authz returned ' + answer.status);

  const decision = answer.decision;
  if (!decision || decision.allowed !== true) return deny(403, 'forbidden');
  return request;
}

import cf from 'cloudfront';

// Viewer-request function on /patterns/markdown-on-demand/*.
// AI agents get a markdown copy of a page, made the first time one asks for it:
//   not an agent, or not a page -> x-markdown: skipped, no call
//   KVS has md:<uri>            -> URI rewritten to the .md object, x-markdown: served, no call
//   no key yet                  -> the HTML as usual, plus one cf.beacon { uri } to the queue,
//                                  x-markdown: queued (x-markdown: failed if cf.beacon threw)
//   GET reset?page=guide.html   -> one cf.beacon { action: reset } to the same queue, a JSON
//                                  answer from the function itself, x-markdown: reset
// A worker behind the queue converts the page, then writes the .md and the KVS key; a reset
// deletes the key, so the next agent request is queued again.
// KVS answers "does markdown exist yet" without spending the one network call.

const QUEUE_ORIGIN_ID = 'markdown-on-demand-queue';
const CONVERT_PATH = '/patterns/convert';
const PAGE_DIR = '/patterns/markdown-on-demand/';
const RESET_URI = PAGE_DIR + 'reset';
const INDEX_DOCUMENT = 'index.html';
const MARKDOWN_KEY_PREFIX = 'md:'; // md:<page uri> -> the .md object's URI, written by the worker
const MARKDOWN_TYPE = 'text/markdown';
const MS_PER_MINUTE = 60000;
// .html under this path only, no dots elsewhere: the worker accepts exactly the same URIs.
const PAGE = /^\/patterns\/markdown-on-demand\/[\w\/-]{1,200}\.html$/;
// An agent says so with Accept, or AWS WAF Bot Control labels it an AI bot. The web ACL writes
// this header on every request here (the bot's name, or none), overwriting any viewer copy.
const WAF_AGENT_HEADER = 'x-amzn-waf-ai-agent';
const NOT_AN_AGENT = 'none';
const MARKDOWN_HEADER = 'x-markdown';
const ERROR_HEADER = 'x-markdown-error';

function headerValue(headers, name) {
  return headers[name] ? headers[name].value : '';
}

function describeError(error) {
  return error.name + ': ' + error.message;
}

function isAgent(headers) {
  const wafAgent = headerValue(headers, WAF_AGENT_HEADER);
  return headerValue(headers, 'accept').indexOf(MARKDOWN_TYPE) !== -1 || (wafAgent !== '' && wafAgent !== NOT_AN_AGENT);
}

// The function's own answer to a reset: JSON, never cached.
function jsonReply(statusCode, verdict, body) {
  return {
    statusCode: statusCode,
    headers: {
      'content-type': { value: 'application/json' },
      'cache-control': { value: 'no-store' },
      [MARKDOWN_HEADER]: { value: verdict },
    },
    body: JSON.stringify(body),
  };
}

// The one network call, fire-and-forget. Throws only for an invalid call (TypeError):
// a bad option, or a second call in one invocation.
function sendToQueue(message) {
  cf.beacon(CONVERT_PATH, {
    originId: QUEUE_ORIGIN_ID,
    method: 'POST',
    headers: { 'content-type': 'application/json' }, // plain strings, not { value } objects
    body: JSON.stringify(message),
    logDeliveryErrors: true, // a delivery failure after the function returned goes to CloudWatch Logs
  });
}

// Forget a page's markdown so the next agent request is queued again. Anyone may ask;
// it only ever names md:<page> for a page this function would convert.
function resetPage(request) {
  const page = request.querystring.page ? PAGE_DIR + request.querystring.page.value : '';
  if (!PAGE.test(page)) return jsonReply(400, 'invalid', { error: 'page must be a .html page under ' + PAGE_DIR });
  try {
    // at: each reset is its own message, never deduplicated with an earlier one.
    sendToQueue({ action: 'reset', uri: page, at: Date.now() });
  } catch (error) {
    return jsonReply(500, 'failed', { error: describeError(error) });
  }
  return jsonReply(200, 'reset', { reset: 'queued', uri: page, note: 'the edge sees it in about a minute' });
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  // Only this function tells the response side what happened: drop viewer-supplied copies.
  delete headers[MARKDOWN_HEADER];
  delete headers[ERROR_HEADER];

  if (request.uri === RESET_URI) return resetPage(request);

  // S3 has no index document below the root: a folder means its index.html.
  if (request.uri.endsWith('/')) request.uri += INDEX_DOCUMENT;
  const uri = request.uri;
  if (!isAgent(headers) || !PAGE.test(uri)) {
    headers[MARKDOWN_HEADER] = { value: 'skipped' };
    return request;
  }

  // 1. KVS. A missing key, or no KVS associated, throws: not converted yet.
  try {
    request.uri = await cf.kvs().get(MARKDOWN_KEY_PREFIX + uri);
    headers[MARKDOWN_HEADER] = { value: 'served' };
    return request;
  } catch (error) {
    // KeyNotFound: fall through and ask for a conversion.
  }

  // 2. Miss: the HTML goes out as usual; one message asks for markdown.
  try {
    // The URI and the minute: the FIFO queue dedups on the body, so a burst is one message,
    // and a page reset a minute ago is not dropped as a repeat of its first conversion.
    sendToQueue({ uri: uri, minute: Math.floor(Date.now() / MS_PER_MINUTE) });
    headers[MARKDOWN_HEADER] = { value: 'queued' };
  } catch (error) {
    headers[MARKDOWN_HEADER] = { value: 'failed' };
    headers[ERROR_HEADER] = { value: describeError(error) };
  }
  return request;
}

// Viewer-response function on /patterns/markdown-on-demand/*. No network call.
// An S3 origin echoes nothing, so this copies the x-markdown verdict that function.js left
// on the request onto the response, and adds Vary: the same URL answers HTML or markdown.
// CloudFront skips viewer-response when the origin returns 400 or higher (a missing page).

const VERDICT_HEADERS = ['x-markdown', 'x-markdown-error'];
const VARY = 'Accept, User-Agent'; // Accept, and the user agent Bot Control labels by

async function handler(event) {
  const requestHeaders = event.request.headers;
  const response = event.response;
  VERDICT_HEADERS.forEach((name) => {
    if (requestHeaders[name]) response.headers[name] = { value: requestHeaders[name].value };
  });
  response.headers['vary'] = { value: VARY };
  return response;
}

import cf from 'cloudfront';
import crypto from 'crypto';

// Viewer-request: a virtual waiting room. Design, cases and the cookie contract: README.

const QUEUE_ORIGIN_ID = 'edge-waiting-room';
const PATH_PREFIX = '/patterns/edge-waiting-room/';
const STATE_KEY = 'queue-state'; // from the admission Lambda: { mode, epoch, serving, step, tick }
const SECRET_KEYS = ['queue-secret-cur', 'queue-secret-prev']; // cur signs, either verifies
const SHARDS = 8; // counter items; the admission Lambda reads the same number
const ADMIT_SECONDS = 120; // wr_a lifetime; renewing it is free while wr_t is below the watermark
const TICKET_SECONDS = 7200;
const STALE_MS = 5 * 60 * 1000; // queue-state older than this: the admission Lambda stopped ticking
const REFRESH_SECONDS = 5;
const TICKET_COOKIE = 'wr_t';
const PASS_COOKIE = 'wr_a';
const COOKIE_ATTRIBUTES = 'Path=' + PATH_PREFIX + '; Secure; HttpOnly; SameSite=Lax';
const JWT_HEADER = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.'; // {"alg":"HS256","typ":"JWT"}, the only header accepted
const DOC = '<!doctype html><meta charset="utf-8">';
const VERDICT_HEADER = 'x-wr';
const PLACE_HEADER = 'x-wr-place';

const headerValue = (headers, name) => (headers[name] ? headers[name].value : '');
const sign = (secret, text) => crypto.createHmac('sha256', secret).update(text).digest('base64url');
const sha256 = (text, encoding) => crypto.createHash('sha256').update(text).digest(encoding);

function signJwt(claims, secret) {
  const signed = JWT_HEADER + Buffer.from(JSON.stringify(claims)).toString('base64url');
  return signed + '.' + sign(secret, signed);
}

// Constant time: timing never tells how much of a signature matched.
function constantTimeEquals(expected, actual) {
  let difference = expected.length ^ actual.length;
  for (let i = 0; i < expected.length; i++) difference |= expected.charCodeAt(i) ^ actual.charCodeAt(i);
  return difference === 0;
}

// The claims of a token this queue signed, or null.
function verifyJwt(cookie, secrets) {
  const token = cookie ? cookie.value : '';
  const dot = token.lastIndexOf('.');
  if (token.indexOf(JWT_HEADER) !== 0 || dot <= JWT_HEADER.length) return null;
  let valid = false;
  for (let i = 0; i < secrets.length; i++) {
    if (constantTimeEquals(sign(secrets[i], token.slice(0, dot)), token.slice(dot + 1))) valid = true;
  }
  try {
    return valid ? JSON.parse(Buffer.from(token.slice(JWT_HEADER.length, dot), 'base64url').toString()) : null;
  } catch (error) {
    return null;
  }
}

// no-store: any answer may carry a ticket or a pass.
function respond(statusCode, verdict, extraHeaders, body) {
  const headers = { 'cache-control': { value: 'no-store' }, [VERDICT_HEADER]: { value: verdict },
    'content-type': { value: 'text/html; charset=utf-8' } };
  const response = { statusCode: statusCode, headers: Object.assign(headers, extraHeaders) };
  if (body) response.body = body;
  return response;
}

function withCookie(response, name, value, maxAge) {
  response.cookies = response.cookies || {};
  response.cookies[name] = { value: value, attributes: COOKIE_ATTRIBUTES + '; Max-Age=' + maxAge };
  return response;
}

function waitingPage(verdict, title, line) {
  const html = DOC + '<meta http-equiv="refresh" content="' + REFRESH_SECONDS + '">' +
    '<title>' + title + '</title><body style="font:18px system-ui;max-width:34em;margin:4em auto">' +
    '<h1>' + title + '</h1><p>' + line + '</p>' +
    '<p><a href="leave">Leave the line</a></p>';
  return respond(200, verdict, { 'retry-after': { value: String(REFRESH_SECONDS) } }, html);
}

// Clears the HttpOnly cookies and aws-waf-token (both Domain forms), so the CAPTCHA comes back.
function leftPage(host, place) {
  const page = respond(200, 'left', { [PLACE_HEADER]: { value: place } },
    DOC + '<title>You left the line</title><p>You left the line. <a href="shop">Join again</a></p>');
  withCookie(withCookie(page, TICKET_COOKIE, '', 0), PASS_COOKIE, '', 0);
  const expired = (domain) => ({ value: '', attributes: 'Path=/; Secure; ' + domain + 'Max-Age=0' });
  const wafToken = [expired(''), expired('Domain=' + host + '; ')];
  page.cookies['aws-waf-token'] = Object.assign(expired(''), { multiValue: wafToken });
  return page;
}

// KVS reads, not network calls; a missing key leaves state null or a secret out.
async function readQueue() {
  const store = cf.kvs();
  const reads = await Promise.allSettled([
    store.get(STATE_KEY, { format: 'json' }), store.get(SECRET_KEYS[0]), store.get(SECRET_KEYS[1]),
  ]);
  return {
    state: reads[0].status === 'fulfilled' ? reads[0].value : null,
    secrets: reads.slice(1).filter((read) => read.status === 'fulfilled' && read.value).map((read) => read.value),
  };
}

// One cf.beacon puts the ticket in a skip set (a set: a replayed cookie frees one place).
function leaveLine(state, ticket, host) {
  if (ticket < 0 || ticket < state.serving) return leftPage(host, 'none');
  try {
    cf.beacon('/patterns/leave', {
      originId: QUEUE_ORIGIN_ID,
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ epoch: state.epoch, ticket: ticket }),
      logDeliveryErrors: true, // late failures go to CloudWatch Logs
    });
    return leftPage(host, 'freed');
  } catch (error) {
    return leftPage(host, 'failed'); // only an invalid call throws
  }
}

// wr_a binds to a hash of WAF token id, user agent and JA4: a copied pass fails.
function clientBinding(headers) {
  const client = [headerValue(headers, 'x-amzn-waf-wr-token-id'), headerValue(headers, 'user-agent'),
    headerValue(headers, 'cloudfront-viewer-ja4-fingerprint')].join('|');
  return sha256(client, 'base64url').slice(0, 22);
}

function positionPage(ticket, state, now) {
  if (now * 1000 - state.tick > STALE_MS) return waitingPage('paused', 'The queue is paused', 'You keep your place in line.');
  const ahead = ticket - state.serving + 1;
  const minutes = Math.ceil(ahead / Math.max(state.step, 1));
  return waitingPage('waiting', 'You are in line', 'Position about <b>' + ahead + '</b>, roughly ' + minutes + ' min.');
}

// The one network call: the shard's counter hands out its next number, or throws.
async function drawTicket(epoch, shard) {
  const enqueueResponse = await cf.fetch('/patterns/enqueue', {
    originId: QUEUE_ORIGIN_ID,
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ epoch: epoch, shard: shard }),
    includeBody: true,
  });
  if (!enqueueResponse.ok) throw new Error('enqueue answered ' + enqueueResponse.status); // 429: API Gateway throttled
  const text = await enqueueResponse.text();
  const ticket = (JSON.parse(text).n - 1) * SHARDS + shard;
  if (!(ticket >= 0)) throw new Error('enqueue sent no counter');
  return ticket;
}

async function handler(event) {
  const request = event.request;
  const headers = request.headers;
  const now = Math.floor(Date.now() / 1000); // JWT times are in seconds
  delete headers[VERDICT_HEADER]; // only this function tells the origin what happened

  const queue = await readQueue();
  const state = queue.state;
  const secrets = queue.secrets;
  // The epoch makes a counter reset safe.
  const claims = state ? verifyJwt(request.cookies[TICKET_COOKIE], secrets) : null;
  const ticket = claims && claims.epoch === state.epoch && typeof claims.ticket === 'number' ? claims.ticket : -1;

  if (request.uri === PATH_PREFIX + 'leave') return leaveLine(state, ticket, headerValue(headers, 'host'));
  if (state && state.mode === 'off') {
    headers[VERDICT_HEADER] = { value: 'off' };
    return request;
  }
  if (!state || !secrets.length) return waitingPage('starting', 'The queue is starting', 'Please wait a moment.');

  const binding = clientBinding(headers);
  const pass = verifyJwt(request.cookies[PASS_COOKIE], secrets);
  if (pass && pass.epoch === state.epoch && pass.exp > now && pass.bnd === binding) {
    headers[VERDICT_HEADER] = { value: 'admitted' };
    return request;
  }

  // In line. Tickets below the watermark are admitted.
  if (ticket >= 0) {
    if (ticket >= state.serving) return positionPage(ticket, state, now);
    const admitted = respond(302, 'admit', { location: { value: request.uri } });
    const newPass = signJwt({ epoch: state.epoch, exp: now + ADMIT_SECONDS, bnd: binding }, secrets[0]);
    return withCookie(admitted, PASS_COOKIE, newPass, ADMIT_SECONDS);
  }

  // No ticket. Only a browser page load may draw one.
  if (request.method !== 'GET' || headerValue(headers, 'accept').indexOf('text/html') === -1) {
    return respond(503, 'browsers-only',
      { 'content-type': { value: 'application/json' }, 'retry-after': { value: String(REFRESH_SECONDS) } },
      '{"waitingRoom":"open this URL in a browser"}');
  }

  // A hash of the request id, not Math.random(): no network call may follow random values.
  const shard = parseInt(sha256(event.context.requestId, 'hex').slice(0, 8), 16) % SHARDS;
  let drawn;
  try {
    drawn = await drawTicket(state.epoch, shard);
  } catch (error) {
    // Fail closed: no ticket, the page retries.
    return waitingPage('busy', 'Busy, retrying', 'The line is very long right now (' + error.name + ').');
  }
  const queued = waitingPage('queued', 'You are in line', 'Your ticket is <b>' + drawn + '</b>. Finding your position...');
  return withCookie(queued, TICKET_COOKIE, signJwt({ epoch: state.epoch, ticket: drawn, iat: now }, secrets[0]), TICKET_SECONDS);
}
